                  setCurrent(idx)
                }}
                className={`h-1.5 rounded-full transition-all duration-300 ${
                  idx === current ? 'w-8 bg-white' : 'w-1.5 bg-white/30 hover:bg-white/50'
                }`}
                aria-label={`Go to slide ${idx + 1}`}
              />
            ))}
          </div>

          <div className="flex items-center gap-2">
            <Button
